let events=loadEvents(),currentId=localStorage.getItem(KEY+':current')||events[0].id,taskFilter='all',taskCategoryFilter='all',partnerFilter='all',mediaFilter='all',communitySub='community',teamExpanded=false,searchGlobal='',users=[],authUser=null,sharedAuditLogs=[],cloudWorkspaceReady=false,cloudQueue=Promise.resolve();
function loadEvents(){try{const x=JSON.parse(localStorage.getItem(KEY));return Array.isArray(x)&&x.length?x:[structuredClone(seed)]}catch{return[structuredClone(seed)]}}
function cloudTask(fn){const task=cloudQueue.then(fn);cloudQueue=task.catch(err=>{console.error('HIVE shared workspace:',err);toast(`Sinkronisasi gagal: ${err.message||'periksa koneksi'}`)});return task}
function save(){localStorage.setItem(KEY,JSON.stringify(events));localStorage.setItem(KEY+':current',currentId);if(cloudWorkspaceReady&&canEdit()){const snapshot=structuredClone(events);snapshot.forEach(e=>delete e.logs);cloudTask(()=>HiveCloud.saveWorkspace(snapshot))}}
function event(){return events.find(x=>x.id===currentId)||events[0]}
function canEdit(){return authUser&&['admin','editor'].includes(authUser.role)}
function audit(action,detail){if(!authUser||!event())return Promise.resolve();const e=event();e.logs=e.logs||[];e.logs.unshift({at:new Date().toISOString(),user:authUser.name,email:authUser.email,action,detail});save();if(!HiveCloud?.session)return Promise.resolve();return cloudTask(()=>HiveCloud.addAudit({eventId:e.id,eventName:e.name,action,detail})).then(()=>refreshSharedAudit())}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function statusKey(s=''){s=String(s).toLowerCase();if(s.includes('done')||s.includes('confirm'))return'confirm';if(s.includes('run')||s.includes('process')||s.includes('scheduled')||s.includes('ongoing'))return'process';if(s.includes('cancel'))return'cancel';if(s.includes('respond')||s.includes('deliver'))return'response';return'open'}
function pill(s){let k=statusKey(s);return `<span class="pill ${k==='confirm'?'done':k==='process'?'running':k==='cancel'?'cancel':k==='response'?'not-delivered':''}">${esc(s||'To do')}</span>`}
function dateShort(s){if(!s)return'—';let d=new Date(s+'T12:00:00');return isNaN(d)?esc(s):d.toLocaleDateString('id-ID',{day:'numeric',month:'short'})}
function dateRange(start,end){if(!start)return'Tanggal belum diatur';const a=new Date(start+'T12:00:00'),b=new Date((end||start)+'T12:00:00');if(isNaN(a))return'Tanggal belum diatur';if(isNaN(b)||start===(end||start))return a.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});const sameYear=a.getFullYear()===b.getFullYear(),sameMonth=sameYear&&a.getMonth()===b.getMonth();if(sameMonth)return `${a.getDate()}–${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`;if(sameYear)return `${a.toLocaleDateString('id-ID',{day:'numeric',month:'short'})} – ${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`;return `${a.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})} – ${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`}
function fmtNum(n){return new Intl.NumberFormat('id-ID').format(Number(n)||0)}
function fmtCurrency(n){return'Rp '+fmtNum(Math.max(0,Number(n)||0))}
function safeDriveLink(value){try{const u=new URL(String(value||''));return u.protocol==='https:'&&['drive.google.com','docs.google.com'].includes(u.hostname)?u.href:''}catch{return''}}
function driveDownloadLink(value){const safe=safeDriveLink(value);if(!safe)return'';const u=new URL(safe),id=u.pathname.match(/\/d\/([^/]+)/)?.[1]||u.searchParams.get('id');if(!id)return safe;if(u.hostname==='docs.google.com')return `${u.origin}${u.pathname.split('/d/')[0]}/d/${encodeURIComponent(id)}/export?format=pdf`;return `https://drive.google.com/uc?export=download&id=${encodeURIComponent(id)}`}
function renderEventMap(e){const map=e.eventMap,content=document.getElementById('eventMapContent'),remove=document.getElementById('removeEventMap');if(!map){content.innerHTML='<p>Belum ada peta. Upload gambar ringan atau PDF layout venue.</p>';remove.classList.add('hidden');return}const name=esc(map.name||'Event map'),link=map.data||'';remove.classList.toggle('hidden',!canEdit());content.innerHTML=map.type==='application/pdf'?`<div class="event-map-file"><span class="map-file-icon">PDF</span><div><b>${name}</b><small>${(Number(map.size)||0)/1048576<1?`${Math.max(1,Math.round((Number(map.size)||0)/1024))} KB`:`${((Number(map.size)||0)/1048576).toFixed(1)} MB`}</small></div><a class="btn btn-outline map-download" href="${link}" download="${name}" target="_blank" rel="noopener">↓ Download map</a></div>`:`<div class="event-map-preview"><a href="${link}" target="_blank" rel="noopener"><img src="${link}" alt="${name}"></a><div class="event-map-file"><b>${name}</b><a class="btn btn-outline map-download" href="${link}" download="${name}">↓ Download map</a></div></div>`}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('File tidak dapat dibaca.'));reader.readAsDataURL(file)})}
async function compressMapImage(file){if(!('createImageBitmap'in window))return fileToDataUrl(file);const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.78));if(!blob)throw new Error('Gambar tidak dapat diproses.');if(blob.size>950000){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.58))}if(!blob||blob.size>1400000)throw new Error('Peta gambar terlalu besar setelah dikompres. Coba gambar yang lebih kecil.');return fileToDataUrl(new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'}))}
async function storeEventMap(file){if(!canEdit())return toast('Akun ini hanya memiliki akses lihat.');if(!file)return;if(file.size>2*1024*1024)return toast('Ukuran file maksimal 2 MB.');if(file.type!=='application/pdf'&&!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Gunakan file PDF, PNG, JPG, atau WebP.');try{const previous=event().eventMap,data=file.type==='application/pdf'?await fileToDataUrl(file):await compressMapImage(file);event().eventMap={name:file.type==='application/pdf'?file.name:file.name.replace(/\.[^.]+$/,'')+'.webp',type:file.type==='application/pdf'?'application/pdf':'image/webp',data,size:file.type==='application/pdf'?file.size:Math.round(data.length*0.75)};try{save()}catch(err){event().eventMap=previous;throw err}audit('Event map updated',`${event().eventMap.name} · ${(event().eventMap.size/1024).toFixed(0)} KB`);render();toast('Event map berhasil disimpan')}catch(err){toast(err.message||'Event map tidak dapat disimpan.')}finally{document.getElementById('eventMapFile').value=''}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function showAuth(mode='login',message='',isError=false){const gate=document.getElementById('authGate'),form=document.getElementById('authForm'),fields=document.getElementById('authFields'),signup=mode==='signup',reset=mode==='reset',messageEl=document.getElementById('authMessage');gate.classList.remove('hidden');form.dataset.mode=mode;document.getElementById('authTitle').textContent=signup?'Buat akun workspace':reset?'Atur password baru':'Masuk ke workspace';messageEl.textContent=message||(signup?'Akun baru akan masuk sebagai viewer, kecuali jika admin mengundang Anda.':reset?'Buat password baru untuk akun Anda.':'Login bersama untuk mengakses event dan activity log.');messageEl.classList.toggle('auth-message-error',isError);messageEl.setAttribute('role',isError?'alert':'status');document.getElementById('authSubmit').textContent=signup?'Buat akun':reset?'Simpan password':'Masuk';document.getElementById('forgotPasswordButton').classList.toggle('hidden',signup||reset);const modeToggle=document.getElementById('authModeToggle');modeToggle.textContent=reset?'Kembali ke masuk':signup?'Sudah punya akun? Masuk':'Belum punya akun? Buat akun';modeToggle.classList.toggle('hidden',reset);fields.innerHTML=signup?field('NAMA LENGKAP','name')+field('EMAIL','email','','email')+field('PASSWORD · MIN. 8 KARAKTER','password','','password'):reset?field('PASSWORD BARU · MIN. 8 KARAKTER','password','','password')+field('ULANGI PASSWORD BARU','confirmPassword','','password'):field('EMAIL','email','','email')+field('PASSWORD · MIN. 8 KARAKTER','password','','password');document.querySelector('#authFields input')?.focus()}
function authErrorMessage(err){const message=String(err?.message||err?.error_description||'').trim(),lower=message.toLowerCase();if(lower.includes('invalid login credentials')||lower.includes('invalid email or password')||lower.includes('invalid password')||lower.includes('user not found'))return'Email atau password salah. Periksa kembali lalu coba lagi.';if(lower.includes('email not confirmed')||lower.includes('email_not_confirmed'))return'Email belum dikonfirmasi. Buka email konfirmasi terlebih dahulu, lalu masuk kembali.';if(lower.includes('too many requests')||lower.includes('rate limit'))return'Terlalu banyak percobaan login. Tunggu sebentar sebelum mencoba lagi.';if(lower.includes('already registered')||lower.includes('user already exists'))return'Email ini sudah terdaftar. Silakan masuk atau gunakan email lain.';if(lower.includes('failed to fetch')||lower.includes('network')||lower.includes('fetch'))return'Tidak dapat terhubung ke layanan login. Periksa koneksi internet lalu coba lagi.';if(lower.includes('expired')||lower.includes('invalid token'))return'Tautan tidak valid atau sudah kedaluwarsa. Minta tautan baru dan coba lagi.';return message||'Login tidak berhasil. Periksa email dan password, lalu coba lagi.'}
let passwordRecoveryPending=false,passwordRecoveryError='';
function beginPasswordRecovery(){const params=new URLSearchParams(location.hash.slice(1)),error=params.get('error_description')||params.get('error_code');if(error){passwordRecoveryPending=true;passwordRecoveryError=error.toLowerCase().includes('expired')||error.toLowerCase().includes('invalid')?'Tautan reset password tidak valid atau sudah kedaluwarsa. Minta tautan baru.':authErrorMessage(new Error(error));HiveCloud.setSession(null);history.replaceState(null,'',location.pathname+location.search+'#overview');return}if(params.get('type')!=='recovery'||!params.get('access_token'))return;HiveCloud.setSession({access_token:params.get('access_token'),refresh_token:params.get('refresh_token')||'',token_type:'bearer',expires_in:Number(params.get('expires_in'))||3600});passwordRecoveryPending=true;history.replaceState(null,'',location.pathname+location.search+'#overview')}
function mapProfile(p){return p?{id:p.id,name:p.full_name||p.email,email:p.email,role:p.role,active:p.active,createdAt:p.created_at}:null}
async function refreshSharedAudit(){if(!HiveCloud.session?.access_token)return;try{sharedAuditLogs=await HiveCloud.auditLogs();renderUsersAudit()}catch(err){console.warn('Activity log refresh failed:',err.message)}}
async function enterWorkspace(user,{logLogin=false}={}){const profile=mapProfile(await HiveCloud.profile(user.id));if(!profile)throw new Error('Profil belum tersedia. Pastikan supabase/setup.sql sudah dijalankan.');if(!profile.active){await HiveCloud.signOut();throw new Error('Akun ini dinonaktifkan. Hubungi admin workspace.')}authUser=profile;users=(await HiveCloud.profiles()).map(mapProfile);let remoteEvents=await HiveCloud.workspace();if(remoteEvents&&Array.isArray(remoteEvents)&&remoteEvents.length){events=remoteEvents;currentId=localStorage.getItem(KEY+':current')||events[0].id;if(!events.some(e=>e.id===currentId))currentId=events[0].id;localStorage.setItem(KEY,JSON.stringify(events))}else if(profile.role==='admin'){cloudWorkspaceReady=true;save()}else throw new Error('Workspace belum memiliki data bersama. Minta admin masuk dan menyiapkan workspace terlebih dahulu.');cloudWorkspaceReady=true;document.getElementById('authGate').classList.add('hidden');applyRolePermissions();render();await refreshSharedAudit();if(logLogin)await audit('Login','Masuk ke shared workspace');}
async function initializeAuth(){if(passwordRecoveryPending){showAuth(passwordRecoveryError?'login':'reset',passwordRecoveryError,Boolean(passwordRecoveryError));return}if(!HiveCloud.configured()){showAuth('login','Konfigurasi Supabase belum tersedia.');return}try{const user=await HiveCloud.currentUser();if(user){await enterWorkspace(user);return}}catch(err){console.error(err);toast(err.message||'Tidak dapat memuat akun workspace.')}showAuth()}
document.getElementById('authModeToggle').addEventListener('click',()=>{const mode=document.getElementById('authForm').dataset.mode;showAuth(mode==='signup'||mode==='reset'?'login':'signup')});
document.getElementById('authForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,data=new FormData(form),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||''),signup=form.dataset.mode==='signup',reset=form.dataset.mode==='reset',name=String(data.get('name')||'').trim();try{if(reset){if(password.length<8)throw new Error('Password minimal 8 karakter.');if(password!==String(data.get('confirmPassword')||''))throw new Error('Konfirmasi password tidak sama.');await HiveCloud.updatePassword(password);await HiveCloud.signOut();passwordRecoveryPending=false;passwordRecoveryError='';showAuth('login','Password berhasil diperbarui. Silakan masuk dengan password baru.');return}if(password.length<8)throw new Error('Password minimal 8 karakter.');const result=signup?await HiveCloud.signUp(email,password,name):await HiveCloud.signIn(email,password);if(!result?.access_token){showAuth('login','Akun terdaftar. Cek email untuk konfirmasi, lalu masuk kembali.');return}const user=result.user||await HiveCloud.currentUser();await enterWorkspace(user,{logLogin:!signup});if(signup)toast('Akun dibuat. Hubungi admin untuk akses editor/admin.');else toast(`Selamat datang, ${authUser.name}`)}catch(err){showAuth(reset?'reset':signup?'signup':'login',authErrorMessage(err),true)}});
document.getElementById('logoutButton').addEventListener('click',async()=>{if(authUser)await audit('Logout','Keluar dari shared workspace');await HiveCloud.signOut();authUser=null;cloudWorkspaceReady=false;sharedAuditLogs=[];closeHiveAi();applyRolePermissions();showAuth()});
function applyRolePermissions(){document.getElementById('profileName').textContent=authUser?.name||'Signed out';document.getElementById('profileRole').textContent=authUser?.role||'User session';document.getElementById('profileInitial').textContent=(authUser?.name||'?').slice(0,2).toUpperCase();document.getElementById('aiChatButton').classList.toggle('hidden',!authUser);const admin=authUser?.role==='admin';document.getElementById('addUserButton').classList.toggle('hidden',!admin);document.querySelectorAll('[data-add],#editEvent,#ticketingEdit,#ticketingStart').forEach(el=>el.classList.toggle('hidden',!canEdit()));document.getElementById('newEventTop').classList.toggle('hidden',!admin);document.getElementById('addRundownItem').classList.toggle('hidden',!canEdit());document.querySelectorAll('[data-task],[data-partner],[data-media],[data-equipment]').forEach(el=>el.disabled=!canEdit());document.getElementById('eventMapUploadButton').classList.toggle('hidden',!canEdit());document.getElementById('removeEventMap').classList.toggle('hidden',!canEdit()||!event()?.eventMap);}
function renderUsersAudit(){const logs=sharedAuditLogs,search=(document.getElementById('auditSearch')?.value||'').toLowerCase();document.getElementById('userCount').textContent=users.length;document.getElementById('auditCount').textContent=logs.length;document.getElementById('currentUserLabel').textContent=authUser?.name||'—';document.getElementById('usersTable').innerHTML=users.map((u,i)=>`<tr><td><span class="item-name">${esc(u.name)}</span></td><td>${esc(u.email)}</td><td><select data-user-role="${i}" ${authUser?.role!=='admin'||u.id===authUser?.id?'disabled':''}>${['admin','editor','viewer'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${u.active?'Aktif':'Nonaktif'}</td><td><button class="text-button" data-user-active="${i}" ${authUser?.role!=='admin'||u.id===authUser?.id?'disabled':''}>${u.active?'Nonaktifkan':'Aktifkan'}</button></td></tr>`).join('');document.getElementById('auditTable').innerHTML=logs.filter(l=>`${l.actor_name} ${l.actor_email} ${l.action} ${l.detail} ${l.event_name}`.toLowerCase().includes(search)).map(l=>`<tr><td>${new Date(l.created_at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}</td><td><span class="item-name">${esc(l.actor_name)}</span><span class="cell-sub">${esc(l.actor_email)}</span></td><td>${esc(l.event_name||'—')}</td><td>${esc(l.action)}</td><td>${esc(l.detail||'—')}</td></tr>`).join('')||'<tr><td colspan="5">Belum ada aktivitas yang cocok.</td></tr>'}
function setPage(name){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+name));document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===name));if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);document.getElementById('sidebar').classList.remove('open');window.scrollTo(0,0)}
function rundownDateLabel(value){if(!value)return'Tanggal belum diatur';const d=new Date(`${value}T12:00:00`);return Number.isNaN(d.getTime())?esc(value):d.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function sortedRundown(e){return(e.rundown||[]).map((item,index)=>({...item,index})).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||String(a.start||'').localeCompare(String(b.start||''))||String(a.end||'').localeCompare(String(b.end||'')))}
function renderRundown(e){const items=sortedRundown(e),days=[...new Set(items.map(item=>item.date||''))];document.getElementById('rundownSummary').innerHTML=`<article class="rundown-stat"><span>EVENT DAYS</span><strong>${days.length}</strong></article><article class="rundown-stat"><span>SCHEDULED ACTIVITIES</span><strong>${items.length}</strong></article><article class="rundown-stat"><span>EVENT WINDOW</span><strong>${esc(dateRange(e.startDate||e.date,e.endDate||e.date||e.startDate))}</strong></article>`;document.getElementById('rundownDays').innerHTML=days.length?days.map(day=>{const rows=items.filter(item=>(item.date||'')===day);return`<article class="panel rundown-day"><div class="rundown-day-head"><div><span class="section-kicker">${day?'EVENT DAY':'DATE NOT SET'}</span><h2>${rundownDateLabel(day)}</h2></div><span class="rundown-day-count">${rows.length} activities</span></div><div class="rundown-timeline">${rows.map(item=>`<div class="rundown-entry"><div class="rundown-time">${esc(item.start||'—')}<span>–</span>${esc(item.end||'—')}</div><div class="rundown-entry-copy"><b>${esc(item.activity||'Untitled activity')}</b></div><div class="rundown-entry-actions"><button class="text-button" data-rundown-edit="${item.index}" ${canEdit()?'':'disabled'}>Edit</button><button class="text-button rundown-delete" data-rundown-delete="${item.index}" ${canEdit()?'':'disabled'}>Delete</button></div></div>`).join('')}</div></article>`}).join(''):'<div class="panel rundown-empty"><span class="rundown-empty-icon">◷</span><h2>Rundown belum dibuat</h2><p>Tambahkan aktivitas satu per satu. Setiap aktivitas bisa memiliki tanggal dan rentang waktu sendiri.</p><button class="btn btn-dark" id="addFirstRundownItem" '+(canEdit()?'':'disabled')+'>＋ Add first schedule</button></div>';const first=document.getElementById('addFirstRundownItem');if(first)first.onclick=()=>openModal('rundown')}
