function printRundown(){const e=event();if(!e)return;const items=sortedRundown(e),days=[...new Set(items.map(item=>item.date||''))];document.getElementById('printRundownSheet').innerHTML=`${reportHeader(e,'EVENT RUNDOWN')}<p class="print-intro">Urutan aktivitas event berdasarkan tanggal dan waktu. Total ${items.length} aktivitas dalam ${days.length} hari.</p>${days.map(day=>{const rows=items.filter(item=>(item.date||'')===day);return`<section class="print-rundown-day"><h2>${rundownDateLabel(day)} <small>${rows.length} activities</small></h2><table class="print-rundown-table"><thead><tr><th style="width:26%">TIME</th><th>ACTIVITY</th></tr></thead><tbody>${rows.map(item=>`<tr><td><b>${esc(item.start||'—')}–${esc(item.end||'—')}</b></td><td>${esc(item.activity||'—')}</td></tr>`).join('')}</tbody></table></section>`}).join('')||'<div class="print-callout">Belum ada aktivitas rundown.</div>'}<footer class="print-footer">${esc(e.name)} · Rundown · ${esc(dateRange(e.startDate||e.date,e.endDate||e.date||e.startDate))}</footer>`;document.body.classList.remove('print-report-mode','print-checklist-mode','print-rundown-mode');document.body.classList.add('print-rundown-mode');window.print()}
