const modalSubmit=document.getElementById('modalForm');modalSubmit.addEventListener('submit',ev=>{if(ev.submitter&&ev.submitter.value==='cancel')return});
document.getElementById('exportTasks').onclick=()=>{const rows=[['Task','Category','Deadline','PIC / Notes','Status'],...event().tasks];const csv=rows.map(r=>r.map(x=>'"'+String(x||'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${event().name.toLowerCase().replaceAll(' ','-')}-tasks.csv`;a.click();URL.revokeObjectURL(a.href)};
document.getElementById('modalForm').addEventListener('submit',ev=>{if(ev.submitter?.value!=='save')return;if(ev.currentTarget.dataset.kind==='ticket'){ev.preventDefault();if(!canEdit())return toast('Akun ini hanya memiliki akses lihat.');const f=new FormData(ev.currentTarget);event().ticketCapacity=f.get('capacity');event().ticketSales=Number(f.get('sold'))||0;event().ticketPrice=f.get('price');audit('Ticketing updated',`${event().ticketSales} tiket terjual dari kapasitas ${event().ticketCapacity}`);save();document.getElementById('modal').close();render();toast('Data ticketing disimpan')}});
function aiText(node,text){node.textContent=String(text||'')}
function addHiveAiMessage(text,who='assistant'){const list=document.getElementById('hiveAiMessages'),bubble=document.createElement('div');bubble.className=`hive-ai-message ${who}`;bubble.textContent=text;list.appendChild(bubble);while(list.children.length>80)list.firstElementChild.remove();list.scrollTop=list.scrollHeight}
function closeHiveAi(){const panel=document.getElementById('hiveAiPanel'),button=document.getElementById('aiChatButton');if(!panel)return;panel.classList.add('hidden');panel.setAttribute('aria-hidden','true');button?.setAttribute('aria-expanded','false')}
function positionHiveAiPanel(){const panel=document.getElementById('hiveAiPanel'),button=document.getElementById('aiChatButton');if(!panel||panel.classList.contains('hidden'))return;const r=button.getBoundingClientRect(),w=panel.offsetWidth,h=panel.offsetHeight;let left=Math.max(12,Math.min(innerWidth-w-12,r.right-w)),top=r.top>h+20?r.top-h-12:Math.min(innerHeight-h-12,r.bottom+12);top=Math.max(12,Math.min(innerHeight-h-12,top));panel.style.left=`${left}px`;panel.style.top=`${top}px`;panel.style.right='auto';panel.style.bottom='auto'}
function toggleHiveAi(){if(!authUser)return;const panel=document.getElementById('hiveAiPanel'),button=document.getElementById('aiChatButton');if(!panel.classList.contains('hidden')){closeHiveAi();return}panel.classList.remove('hidden');panel.setAttribute('aria-hidden','false');button.setAttribute('aria-expanded','true');if(!panel.dataset.started){addHiveAiMessage(`Halo, saya Hive AI. Saya bisa membantu membaca data ${event()?.name||'event'} di dashboard ini—misalnya prioritas task, status sponsor, jadwal media, logistik, tim, atau activity log.`);panel.dataset.started='true'}requestAnimationFrame(()=>{positionHiveAiPanel();document.getElementById('hiveAiInput').focus()})}
function hiveAiAnswer(raw){const e=event();if(!e)return'Tidak ada event aktif yang dapat saya baca.';const q=String(raw||'').toLowerCase(),tasks=e.tasks||[],partners=e.partners||[],media=e.media||[],equipment=e.equipment||[],team=e.team||[],communities=e.communities||[],kol=e.kol||[],logs=e.logs||[];const scoped=['task','produksi','deadline','sponsor','partner','brand','cash','product','produk','media','post','posting','content','konten','rate','jadwal','logistik','equipment','barang','map','peta','team','tim','crew','role','peran','komunitas','community','kol','creator','athlete','ticket','tiket','event','progress','status','aktivitas','activity','update','volunteer','relawan','proposal'];
 if(!scoped.some(k=>q.includes(k))){const hit=[...tasks.map(x=>x.join(' ')),...partners.map(x=>x.join(' ')),...media.map(x=>x.join(' ')),...equipment.map(x=>x.join(' ')),...team.map(x=>x.join(' ')),...communities.map(x=>x.join(' ')),...kol.map(x=>x.join(' '))].some(row=>row.toLowerCase().split(/\s+/).some(w=>w.length>3&&q.includes(w)));if(!hit)return'Saya hanya membantu topik dalam dashboard event: task & deadline, sponsor, media dan jadwal posting, logistik, team, komunitas/KOL, ticketing, proposal/map, dan activity log.'}
 const countStatus=(rows,i,key)=>rows.filter(x=>statusKey(x[i])===key).length,taskDone=countStatus(tasks,4,'confirm'),partnerDone=countStatus(partners,2,'confirm'),partnerPending=partners.length-partnerDone,cash=partners.reduce((s,p)=>s+(Number(p[4])||0),0),product=partners.reduce((s,p)=>s+(Number(p[5])||0),0);
 const shortList=(rows,format,limit=6)=>rows.slice(0,limit).map(format).join('\n')+(rows.length>limit?`\n+ ${rows.length-limit} lainnya`:''),outOfScope='Saya hanya bisa menjawab berdasarkan daftar dan data pada dashboard event aktif.';
 if(/task|produksi|deadline|prioritas/.test(q)){const attention=tasks.filter(t=>statusKey(t[4])!=='confirm'),overdue=attention.filter(t=>t[2]&&/^\d{4}-\d\d-\d\d$/.test(t[2])&&new Date(t[2]+'T23:59:59')<new Date());if(/selesai|done|progress|ringkas|summary/.test(q)&&!(/perlu|prioritas|deadline|terlambat/.test(q)))return`Task ${e.name}: ${tasks.length} total, ${taskDone} selesai, ${attention.length} masih terbuka (${tasks.length?Math.round(taskDone/tasks.length*100):0}% selesai).${overdue.length?` ${overdue.length} melewati deadline.`:''}`;const focus=overdue.length?overdue:attention;return focus.length?`Ada ${attention.length} task yang belum selesai${overdue.length?`, termasuk ${overdue.length} lewat deadline`:''}.${focus.length?'\n'+shortList(focus,(t)=>`• ${t[0]} · ${t[1]||'Uncategorized'} · ${t[4]||'—'}${t[2]?` · ${dateShort(t[2])}`:''}`,7):''}`:`Semua ${tasks.length} task sudah selesai.`}
 if(/sponsor|partner|brand|cash|product|produk/.test(q)){if(/cash|product|produk|revenue|nilai|value|uang|nominal/.test(q))return`Nilai sponsor saat ini: cash ${fmtCurrency(cash)} dan product support ${fmtCurrency(product)}. Total kontribusi ${fmtCurrency(cash+product)} dari ${partners.length} catatan sponsor.`;const pending=partners.filter(p=>statusKey(p[2])!=='confirm');return`${partnerDone} dari ${partners.length} sponsor berstatus confirmed; ${partnerPending} masih perlu follow-up. Cash ${fmtCurrency(cash)} · product support ${fmtCurrency(product)}.${pending.length?'\n'+shortList(pending,p=>`• ${p[0]} · ${p[1]||'Uncategorized'} · ${p[2]||'—'}`,6):''}`}
 if(/media|post|posting|content|rate|jadwal/.test(q)){const total=media.reduce((s,m)=>s+(Number(m[2])||0),0),scheduled=media.filter(m=>statusKey(m[1])==='process');if(/rate|revenue|nilai|biaya|total/.test(q))return`Total rate placement tercatat ${fmtCurrency(total)} untuk ${media.length} placement.`;const rows=media.filter(m=>/jadwal|schedule|berikut|next|post/.test(q)?m[3]&&m[3]!=='—':statusKey(m[1])!=='confirm');return`${scheduled.length} placement berstatus scheduled dari ${media.length} total; total rate ${fmtCurrency(total)}.${rows.length?'\n'+shortList(rows,m=>`• ${m[0]} · ${m[1]||'—'} · ${m[3]||'Belum dijadwalkan'}${Number(m[2])?` · ${fmtCurrency(m[2])}`:''}`,6):'\nBelum ada detail jadwal pada daftar media.'}`}
 if(/logistik|equipment|barang|checklist|map|peta/.test(q)){const unchecked=equipment.filter(x=>!x[4]);if(/map|peta/.test(q))return e.eventMap?`Event map tersedia: ${e.eventMap.name||'Event map'}. Buka halaman Logistics untuk melihat atau mengunduhnya.`:'Belum ada event map yang diunggah di halaman Logistics.';return`${equipment.length-unchecked.length} dari ${equipment.length} item equipment sudah dicek; ${unchecked.length} belum dicek.${unchecked.length?'\n'+shortList(unchecked,x=>`• ${x[0]} · PIC ${x[1]||'—'} · ${x[2]||'Qty belum diisi'}`,6):''}`}
 if(/team|tim|crew|role|peran|volunteer|relawan/.test(q))return`Ada ${team.length} role team yang tercatat.${team.length?'\n'+shortList(team,t=>`• ${t[0]}: ${t[1]||'Belum ditentukan'}`,8):''}`;
 if(/komunitas|community|kol|creator|athlete/.test(q))return`Daftar audience mencatat ${communities.length} komunitas dan ${kol.length} KOL/athlete.${communities.length?'\nKomunitas: '+shortList(communities,c=>`• ${c[0]} · ${c[2]||c[3]||'Status belum diisi'}`,5):''}`;
 if(/ticket|tiket/.test(q)){const cap=Number(e.ticketCapacity)||0,sold=Number(e.ticketSales)||0;return cap?`${fmtNum(sold)} dari ${fmtNum(cap)} tiket terjual (${Math.round(sold/cap*100)}%); tersisa ${fmtNum(Math.max(0,cap-sold))}.`:`Belum ada kapasitas ticketing yang dicatat untuk event ini.`}
 if(/log|aktivitas|activity|siapa|update/.test(q)){const recent=logs.slice(0,5);return recent.length?`5 aktivitas terakhir pada event ini:\n${shortList(recent,l=>`• ${new Date(l.at).toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'})} · ${l.user||'User'} · ${l.action||'Update'}${l.detail?`: ${l.detail}`:''}`,5)}`:'Belum ada activity log untuk event ini.'}
 if(/event|tanggal|lokasi|venue|format|proposal/.test(q)){if(/proposal/.test(q))return e.proposalLink?'Link proposal tersedia di halaman Overview.':'Belum ada link proposal yang dicatat di Overview.';return`${e.name||'Event'} berlangsung ${dateRange(e.startDate||e.date,e.endDate||e.startDate||e.date)} di ${e.venue||'lokasi belum diatur'}.${e.format?` Format: ${e.format}.`:''}`}
 const needle=q.split(/\s+/).filter(w=>w.length>2),matches=[];for(const [label,rows,nameAt] of [['Task',tasks,0],['Sponsor',partners,0],['Media',media,0],['Equipment',equipment,0],['Team',team,0],['Community',communities,0],['KOL',kol,0]])for(const row of rows)if(needle.some(n=>row.join(' ').toLowerCase().includes(n)))matches.push(`${label}: ${row[nameAt]} · ${row.slice(1,4).filter(Boolean).join(' · ')}`);return matches.length?`Saya menemukan data berikut:\n${shortList(matches,x=>`• ${x}`,6)}`:outOfScope
}
function sendHiveAiMessage(text){const value=String(text||'').trim();if(!value)return;addHiveAiMessage(value,'user');document.getElementById('hiveAiInput').value='';addHiveAiMessage(hiveAiAnswer(value));document.getElementById('hiveAiInput').focus()}
document.getElementById('hiveAiForm').addEventListener('submit',ev=>{ev.preventDefault();sendHiveAiMessage(document.getElementById('hiveAiInput').value)});document.getElementById('hiveAiSuggestions').addEventListener('click',ev=>{const b=ev.target.closest('[data-ai-question]');if(b)sendHiveAiMessage(b.dataset.aiQuestion)});document.getElementById('hiveAiClose').addEventListener('click',()=>{closeHiveAi();document.getElementById('aiChatButton').focus()});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!document.getElementById('hiveAiPanel').classList.contains('hidden'))closeHiveAi()});
function setupAiButtonDrag(){const button=document.getElementById('aiChatButton'),key='hive-event-dashboard:ai-button-position';let dragging=false,moved=false,startX=0,startY=0,offsetX=0,offsetY=0;const clamp=()=>{const r=button.getBoundingClientRect();return{x:Math.max(8,Math.min(window.innerWidth-r.width-8,r.left)),y:Math.max(8,Math.min(window.innerHeight-r.height-8,r.top))}};try{const saved=JSON.parse(localStorage.getItem(key));if(Number.isFinite(saved?.x)&&Number.isFinite(saved?.y)){const p={x:Math.max(8,Math.min(window.innerWidth-button.offsetWidth-8,saved.x)),y:Math.max(8,Math.min(window.innerHeight-button.offsetHeight-8,saved.y))};button.style.left=`${p.x}px`;button.style.top=`${p.y}px`;button.style.right='auto';button.style.bottom='auto'}}catch{}button.addEventListener('pointerdown',ev=>{if(ev.button!==0)return;dragging=true;moved=false;startX=ev.clientX;startY=ev.clientY;const r=button.getBoundingClientRect();offsetX=ev.clientX-r.left;offsetY=ev.clientY-r.top;button.setPointerCapture(ev.pointerId)});button.addEventListener('pointermove',ev=>{if(!dragging)return;if(!moved&&Math.hypot(ev.clientX-startX,ev.clientY-startY)>4){moved=true;button.classList.add('is-dragging')}if(!moved)return;const x=Math.max(8,Math.min(window.innerWidth-button.offsetWidth-8,ev.clientX-offsetX)),y=Math.max(8,Math.min(window.innerHeight-button.offsetHeight-8,ev.clientY-offsetY));button.style.left=`${x}px`;button.style.top=`${y}px`;button.style.right='auto';button.style.bottom='auto';positionHiveAiPanel()});button.addEventListener('pointerup',()=>{dragging=false;if(moved){const p=clamp();try{localStorage.setItem(key,JSON.stringify(p))}catch{}setTimeout(()=>button.classList.remove('is-dragging'),0)}});button.addEventListener('pointercancel',()=>{dragging=false;moved=false;button.classList.remove('is-dragging')});button.addEventListener('click',ev=>{if(moved){ev.preventDefault();ev.stopPropagation();moved=false;return}toggleHiveAi()});window.addEventListener('resize',()=>{if(button.style.left){const p=clamp();button.style.left=`${p.x}px`;button.style.top=`${p.y}px`;try{localStorage.setItem(key,JSON.stringify(p))}catch{}}positionHiveAiPanel()})}
setupAiButtonDrag();applyRolePermissions();showAuth('login');beginPasswordRecovery();initializeAuth();
